-- PT105-S4-Q23. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT105-S4-Q23$batch12$ AND q.stimulus=$batch12$Donna claims to have found the museum's current exhibition of bronzes from Benin less interesting than many of the other exhibitions recently put on by the museum. According to all the critical reviews, however, the Benin exhibition is more interesting than any other exhibition that the museum has put on in years. Therefore, Donna's claim must be false.$batch12$ AND q.prompt=$batch12$Which one of the following arguments contains flawed reasoning that is most similar to the flawed reasoning in the argument above?$batch12$ AND q.correct_choice=$batch12$D$batch12$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT105-S4-Q23$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT105-S4-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Donna's claim must be false.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Donna found the Benin exhibition less interesting than others. All the critics say it is the most interesting in years.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Donna is reporting a personal reaction. The critics' opinion can't show Donna didn't have that reaction. The flaw: using others' judgment to refute someone's report of personal taste.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Find an argument that refutes a claim about personal taste with what others think.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT105-S4-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$Whether a task is finished is a fact, not a matter of taste. The supervisor's word is relevant evidence.$batch12$), ($batch12$B$batch12$, $batch12$Morris was out of the country. That is factual evidence, and it does show the claim false.$batch12$), ($batch12$C$batch12$, $batch12$This pits two people's reports about motives against each other. No outside consensus about taste.$batch12$), ($batch12$D$batch12$, $batch12$Loren says the fish tastes good. Food experts say it's dreadful, so the argument calls Loren's claim false. Same move.$batch12$), ($batch12$E$batch12$, $batch12$The atlas gives a fact about mountain heights. That does refute Douglas's claim.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT105-S4-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
